@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400&family=DM+Sans:wght@300;400;500;700&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --viewer-page: #f7f3ec;
  --viewer-surface: rgba(254, 250, 245, 0.94);
  --viewer-surface-muted: #ede7da;
  --viewer-border: #ddd3c3;
  --viewer-text: #3d342a;
  --viewer-text-muted: #7c6f64;
  --viewer-primary: #7a9e7e;
  --viewer-primary-strong: #5c7d60;
  --viewer-success: #16a34a;
  --viewer-warning: #f59e0b;
  --viewer-danger: #ef4444;
  --viewer-radius-lg: 24px;
  --viewer-radius-md: 18px;
  --viewer-shadow: 0 18px 42px rgba(90, 70, 50, 0.12);
  --viewer-dock-height: 58px;
  --viewer-dock-offset: 20px;
  --viewer-dock-content-gap: calc(var(--viewer-dock-height) + var(--viewer-dock-offset) + 24px);
  --background: 0 0% 100%;
  --foreground: 222.2 84% 4.9%;
  --card: 0 0% 100%;
  --card-foreground: 222.2 84% 4.9%;
  --border: 214.3 31.8% 91.4%;
  --input: 214.3 31.8% 91.4%;
  --primary: 262.1 83.3% 57.8%;
  --primary-foreground: 210 40% 98%;
  --secondary: 210 40% 96.1%;
  --secondary-foreground: 222.2 47.4% 11.2%;
  --muted: 210 40% 96.1%;
  --muted-foreground: 215.4 16.3% 46.9%;
  --accent: 210 40% 96.1%;
  --accent-foreground: 222.2 47.4% 11.2%;
  --destructive: 0 84.2% 60.2%;
  --destructive-foreground: 210 40% 98%;
  --ring: 262.1 83.3% 57.8%;
  --radius: 0.5rem;
  color: var(--viewer-text);
  background: var(--viewer-page);
  font-family: "DM Sans", "Avenir Next", "Segoe UI", sans-serif;
  color-scheme: light;
}

:root[data-theme='dark'] {
  --viewer-page: #07111f;
  --viewer-surface: #0f1b2f;
  --viewer-surface-muted: #12213a;
  --viewer-border: #223554;
  --viewer-text: #f8fafc;
  --viewer-text-muted: #9fb0cc;
  --viewer-primary: #8b5cf6;
  --viewer-primary-strong: #60a5fa;
  --viewer-shadow: 0 20px 48px rgba(2, 6, 23, 0.42);
  --background: 222.2 84% 4.9%;
  --foreground: 210 40% 98%;
  --card: 222.2 84% 4.9%;
  --card-foreground: 210 40% 98%;
  --border: 217.2 32.6% 17.5%;
  --input: 217.2 32.6% 17.5%;
  --primary: 263.4 70% 50.4%;
  --primary-foreground: 210 40% 98%;
  --secondary: 217.2 32.6% 17.5%;
  --secondary-foreground: 210 40% 98%;
  --muted: 217.2 32.6% 17.5%;
  --muted-foreground: 215 20.2% 65.1%;
  --accent: 217.2 32.6% 17.5%;
  --accent-foreground: 210 40% 98%;
  --destructive: 0 62.8% 30.6%;
  --destructive-foreground: 210 40% 98%;
  --ring: 263.4 70% 50.4%;
}

@media (max-width: 767px) {
  :root {
    --viewer-dock-height: 64px;
    --viewer-dock-offset: 12px;
    --viewer-dock-content-gap: calc(var(--viewer-dock-height) + var(--viewer-dock-offset) + 18px);
  }
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  min-height: 100%;
}

html {
  font-size: 15px;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background:
    radial-gradient(ellipse 56rem 34rem at 10% 12%, rgba(168, 197, 172, 0.18) 0%, transparent 62%),
    radial-gradient(ellipse 42rem 28rem at 90% 78%, rgba(196, 149, 106, 0.14) 0%, transparent 62%),
    radial-gradient(ellipse 34rem 24rem at 74% 18%, rgba(169, 154, 180, 0.13) 0%, transparent 62%),
    radial-gradient(ellipse 32rem 22rem at 42% 55%, rgba(212, 184, 150, 0.11) 0%, transparent 64%),
    linear-gradient(180deg, #faf6f0 0%, #f7f3ec 100%);
}

:root[data-theme='dark'] body {
  background:
    radial-gradient(circle at top left, rgba(96, 165, 250, 0.2), transparent 26%),
    radial-gradient(circle at top right, rgba(168, 85, 247, 0.18), transparent 28%),
    linear-gradient(180deg, rgba(2, 6, 23, 0.95), rgba(7, 17, 31, 1));
}

.viewer-full-screen-loader {
  min-height: 100svh;
}

.viewer-boot-splash {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background:
    radial-gradient(ellipse 56rem 34rem at 10% 12%, rgba(168, 197, 172, 0.18) 0%, transparent 62%),
    radial-gradient(ellipse 42rem 28rem at 90% 78%, rgba(196, 149, 106, 0.14) 0%, transparent 62%),
    radial-gradient(ellipse 34rem 24rem at 74% 18%, rgba(169, 154, 180, 0.13) 0%, transparent 62%),
    radial-gradient(ellipse 32rem 22rem at 42% 55%, rgba(212, 184, 150, 0.11) 0%, transparent 64%),
    linear-gradient(180deg, #faf6f0 0%, #f7f3ec 100%);
  transition: opacity 280ms ease, visibility 280ms ease;
}

:root[data-theme='dark'] .viewer-boot-splash {
  background:
    radial-gradient(circle at top left, rgba(96, 165, 250, 0.2), transparent 26%),
    radial-gradient(circle at top right, rgba(168, 85, 247, 0.18), transparent 28%),
    linear-gradient(180deg, rgba(2, 6, 23, 0.96), rgba(7, 17, 31, 1));
}

.viewer-boot-splash--react {
  position: relative;
}

.viewer-boot-splash[data-state='exit'] {
  opacity: 0;
  visibility: hidden;
}

.viewer-boot-splash__backdrop {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 50% 28%, rgba(255, 255, 255, 0.68), transparent 20%),
    radial-gradient(circle at 50% 65%, rgba(255, 244, 227, 0.44), transparent 22%);
  pointer-events: none;
}

:root[data-theme='dark'] .viewer-boot-splash__backdrop {
  background:
    radial-gradient(circle at 50% 28%, rgba(148, 197, 255, 0.18), transparent 20%),
    radial-gradient(circle at 50% 65%, rgba(168, 85, 247, 0.16), transparent 22%);
}

.viewer-boot-splash__core {
  position: relative;
  display: flex;
  width: min(100%, 26rem);
  flex-direction: column;
  align-items: center;
  gap: 1rem;
  padding: 2rem;
  text-align: center;
}

.viewer-boot-splash__logo-shell {
  position: relative;
  display: block;
  width: 7.5rem;
  height: 7.5rem;
}

.viewer-boot-splash__halo,
.viewer-boot-splash__ring,
.viewer-boot-splash__planet {
  position: absolute;
  inset: 0;
