  animation: viewer-boot-halo 2.5s ease-in-out infinite;
}

:root[data-theme='dark'] .viewer-boot-splash__halo {
  background: radial-gradient(circle, rgba(96, 165, 250, 0.26) 0%, rgba(96, 165, 250, 0) 72%);
}

.viewer-boot-splash__ring {
  border: 1px solid rgba(122, 158, 126, 0.28);
}

.viewer-boot-splash__ring--outer {
  inset: -0.1rem;
  animation: viewer-boot-spin 7.5s linear infinite;
}

.viewer-boot-splash__ring--inner {
  inset: 0.6rem;
  border-color: rgba(196, 149, 106, 0.28);
  animation: viewer-boot-spin-reverse 5.4s linear infinite;
}

:root[data-theme='dark'] .viewer-boot-splash__ring {
  border-color: rgba(148, 197, 255, 0.26);
}

:root[data-theme='dark'] .viewer-boot-splash__ring--inner {
  border-color: rgba(196, 181, 253, 0.22);
}

