}

.viewer-botanical-button--warm {
  border: 1px solid #e1c19d;
  background: linear-gradient(145deg, #d4b896 0%, #c4956a 100%);
  color: #fff;
  box-shadow: 0 14px 30px rgba(196, 149, 106, 0.22);
}

.viewer-botanical-button--ghost {
  border: 1px solid var(--viewer-border);
  background: transparent;
  color: #7a6b5e;
}

.viewer-botanical-notice {
  border-radius: 22px;
  border: 1px solid var(--viewer-border);
  padding: 0.95rem 1rem;
  font-size: 0.92rem;
