}

.viewer-botanical-notice--success {
  border-color: #c7ddca;
  background: #eef6ef;
  color: #49664d;
}

.viewer-botanical-notice--error {
  border-color: #e6c8c2;
  background: #fbefed;
  color: #9d554d;
}

.viewer-botanical-notice--info {
  border-color: #e0d4c1;
  background: #f7f1e7;
  color: #886947;
}

@keyframes home-course-card-slide-forward {
  from {
    opacity: 0;
    transform: translateX(16px) translateY(4px);
  }

  to {
    opacity: 1;
    transform: translateX(0) translateY(0);
  }
