.viewer-boot-splash {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background:
    radial-gradient(ellipse 56rem 34rem at 10% 12%, rgba(168, 197, 172, 0.18) 0%, transparent 62%),
    radial-gradient(ellipse 42rem 28rem at 90% 78%, rgba(196, 149, 106, 0.14) 0%, transparent 62%),
    radial-gradient(ellipse 34rem 24rem at 74% 18%, rgba(169, 154, 180, 0.13) 0%, transparent 62%),
    radial-gradient(ellipse 32rem 22rem at 42% 55%, rgba(212, 184, 150, 0.11) 0%, transparent 64%),
    linear-gradient(180deg, #faf6f0 0%, #f7f3ec 100%);
  transition: opacity 280ms ease, visibility 280ms ease;
}

:root[data-theme='dark'] .viewer-boot-splash {
  background:
    radial-gradient(circle at top left, rgba(96, 165, 250, 0.2), transparent 26%),
    radial-gradient(circle at top right, rgba(168, 85, 247, 0.18), transparent 28%),
    linear-gradient(180deg, rgba(2, 6, 23, 0.96), rgba(7, 17, 31, 1));
}

.viewer-boot-splash--react {
  position: relative;
}

.viewer-boot-splash[data-state='exit'] {
  opacity: 0;
  visibility: hidden;
}

.viewer-boot-splash__backdrop {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 50% 28%, rgba(255, 255, 255, 0.68), transparent 20%),
    radial-gradient(circle at 50% 65%, rgba(255, 244, 227, 0.44), transparent 22%);
  pointer-events: none;
}

:root[data-theme='dark'] .viewer-boot-splash__backdrop {
  background:
    radial-gradient(circle at 50% 28%, rgba(148, 197, 255, 0.18), transparent 20%),
    radial-gradient(circle at 50% 65%, rgba(168, 85, 247, 0.16), transparent 22%);
}

.viewer-boot-splash__core {
  position: relative;
  display: flex;
  width: min(100%, 26rem);
  flex-direction: column;
  align-items: center;
  gap: 1rem;
  padding: 2rem;
  text-align: center;
}

.viewer-boot-splash__logo-shell {
  position: relative;
  display: block;
  width: 7.5rem;
  height: 7.5rem;
}

.viewer-boot-splash__halo {
  position: absolute;
  inset: -0.9rem;
  border-radius: 999px;
  background: radial-gradient(circle, rgba(168, 197, 172, 0.3) 0%, rgba(168, 197, 172, 0) 72%);
  animation: viewer-boot-halo 2.5s ease-in-out infinite;
}

:root[data-theme='dark'] .viewer-boot-splash__halo {
  background: radial-gradient(circle, rgba(96, 165, 250, 0.26) 0%, rgba(96, 165, 250, 0) 72%);
}

.viewer-boot-splash__atom {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.viewer-boot-nucleus {
  transform-origin: 60px 60px;
  animation: viewer-boot-nucleus 3.8s ease-in-out infinite;
}

:root[data-theme='dark'] .viewer-boot-splash__atom .vb-orbit-1 {
  stroke: rgba(148, 197, 255, 0.45);
}

:root[data-theme='dark'] .viewer-boot-splash__atom .vb-orbit-2 {
  stroke: rgba(148, 197, 255, 0.30);
}

:root[data-theme='dark'] .viewer-boot-splash__atom .vb-orbit-3 {
  stroke: rgba(196, 181, 253, 0.35);
}

:root[data-theme='dark'] .viewer-boot-splash__atom .vb-electron-1 {
  fill: #60a5fa;
}

:root[data-theme='dark'] .viewer-boot-splash__atom .vb-electron-2 {
  fill: #818cf8;
}

:root[data-theme='dark'] .viewer-boot-splash__atom .vb-electron-3 {
  fill: #c084fc;
}

:root[data-theme='dark'] .viewer-boot-splash__atom .vb-nucleus-circle {
