  letter-spacing: -0.04em;
  color: #5c7d60;
}

:root[data-theme='dark'] .viewer-boot-splash__brand {
  color: #d3def4;
}

.viewer-boot-splash__status-row {
  display: inline-flex;
  align-items: center;
  gap: 0.7rem;
  border-radius: 999px;
  border: 1px solid rgba(221, 211, 195, 0.92);
  background: rgba(255, 252, 247, 0.82);
  padding: 0.8rem 1.1rem;
  color: #7b6f63;
  font-size: 0.92rem;
  font-weight: 700;
  box-shadow:
    0 18px 38px rgba(90, 70, 50, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.72);
  backdrop-filter: blur(14px);
}

:root[data-theme='dark'] .viewer-boot-splash__status-row {
  border-color: rgba(34, 53, 84, 0.9);
  background: rgba(15, 27, 47, 0.84);
  color: #acc0dd;
  box-shadow:
    0 18px 38px rgba(2, 6, 23, 0.28),
    inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.viewer-boot-splash__status-copy {
  display: inline-block;
}

.viewer-boot-splash__dots {
  display: inline-flex;
  gap: 0.32rem;
}

.viewer-boot-splash__dots span {
  width: 0.38rem;
  height: 0.38rem;
  border-radius: 999px;
  background: currentColor;
  animation: viewer-boot-dot 1.15s ease-in-out infinite;
}

.viewer-boot-splash__dots span:nth-child(2) {
  animation-delay: 0.16s;
}

.viewer-boot-splash__dots span:nth-child(3) {
  animation-delay: 0.32s;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
select,
textarea {
  font: inherit;
}

.viewer-surface {
  background: var(--viewer-surface);
  border: 1px solid var(--viewer-border);
  border-radius: var(--viewer-radius-md);
  box-shadow: var(--viewer-shadow);
  backdrop-filter: blur(14px);
}

.viewer-panel {
  border: 1px solid rgba(221, 211, 195, 0.92);
  background:
    radial-gradient(circle at top left, rgba(255, 255, 255, 0.55), transparent 38%),
    rgba(254, 250, 245, 0.88);
  box-shadow:
    0 28px 64px rgba(90, 70, 50, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.66);
  backdrop-filter: blur(20px);
}

.viewer-botanical-heading {
  font-family: "Cormorant Garamond", serif;
  font-weight: 600;
  letter-spacing: -0.04em;
  color: var(--viewer-text);
}

.viewer-botanical-eyebrow {
  color: #93857a;
  font-size: 0.76rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.viewer-botanical-input {
  width: 100%;
  border-radius: 20px;
  border: 1px solid var(--viewer-border);
  background: rgba(255, 252, 247, 0.92);
  padding: 0.85rem 1rem;
  color: var(--viewer-text);
  box-shadow: inset 0 1px 3px rgba(90, 70, 50, 0.05);
  outline: none;
  transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
}

.viewer-botanical-input::placeholder {
  color: #aa9d93;
}

.viewer-botanical-input:focus {
  border-color: #b7ccb8;
  box-shadow:
    0 0 0 3px rgba(122, 158, 126, 0.14),
    inset 0 1px 3px rgba(90, 70, 50, 0.05);
}

.viewer-botanical-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  border-radius: 999px;
  border: 1px solid var(--viewer-border);
  background: rgba(255, 252, 247, 0.88);
  padding: 0.5rem 0.9rem;
  color: #7a6b5e;
  font-size: 0.76rem;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.viewer-botanical-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  border-radius: 999px;
  padding: 0.82rem 1.35rem;
  font-size: 0.92rem;
  font-weight: 700;
  transition:
    transform 160ms ease,
    box-shadow 160ms ease,
    background 160ms ease,
    border-color 160ms ease,
    color 160ms ease;
}

.viewer-botanical-button:hover {
  transform: translateY(-1px);
}

.viewer-botanical-button:disabled {
  opacity: 0.56;
  transform: none;
  cursor: not-allowed;
}

.viewer-botanical-button--primary {
  border: 1px solid #adc9b0;
  background: linear-gradient(145deg, #a8c5ac 0%, #7a9e7e 100%);
  color: #fff;
  box-shadow: 0 14px 30px rgba(122, 158, 126, 0.24);
}

.viewer-botanical-button--secondary {
  border: 1px solid var(--viewer-border);
  background: rgba(255, 252, 247, 0.92);
  color: var(--viewer-text);
  box-shadow: 0 10px 24px rgba(90, 70, 50, 0.08);
}

.viewer-botanical-button--warm {
  border: 1px solid #e1c19d;
  background: linear-gradient(145deg, #d4b896 0%, #c4956a 100%);
  color: #fff;
  box-shadow: 0 14px 30px rgba(196, 149, 106, 0.22);
}

.viewer-botanical-button--ghost {
  border: 1px solid var(--viewer-border);
  background: transparent;
  color: #7a6b5e;
}

.viewer-botanical-notice {
  border-radius: 22px;
  border: 1px solid var(--viewer-border);
  padding: 0.95rem 1rem;
  font-size: 0.92rem;
  font-weight: 600;
}

.viewer-botanical-notice--success {
  border-color: #c7ddca;
  background: #eef6ef;
  color: #49664d;
}

.viewer-botanical-notice--error {
  border-color: #e6c8c2;
  background: #fbefed;
  color: #9d554d;
}

.viewer-botanical-notice--info {
  border-color: #e0d4c1;
  background: #f7f1e7;
  color: #886947;
}

@keyframes home-course-card-slide-forward {
  from {
    opacity: 0;
    transform: translateX(16px) translateY(4px);
  }

  to {
    opacity: 1;
    transform: translateX(0) translateY(0);
  }
}

@keyframes viewer-boot-spin {
  from {
    transform: rotate(0deg);
  }

  to {
    transform: rotate(360deg);
  }
}

@keyframes viewer-boot-spin-reverse {
  from {
    transform: rotate(360deg);
  }

  to {
    transform: rotate(0deg);
  }
}

@keyframes viewer-boot-halo {
  0%,
  100% {
    transform: scale(0.92);
    opacity: 0.72;
  }

  50% {
    transform: scale(1.06);
    opacity: 1;
  }
}

@keyframes viewer-boot-dot {
  0%,
  80%,
  100% {
    transform: translateY(0);
    opacity: 0.4;
  }

  40% {
    transform: translateY(-0.28rem);
    opacity: 1;
  }
}

@keyframes home-course-card-slide-backward {
  from {
    opacity: 0;
    transform: translateX(-16px) translateY(4px);
  }

  to {
    opacity: 1;
    transform: translateX(0) translateY(0);
  }
}

.home-course-card-content {
  will-change: transform, opacity;
}

.home-course-card-content--forward {
  animation: home-course-card-slide-forward 280ms cubic-bezier(0.22, 1, 0.36, 1);
}

.home-course-card-content--backward {
  animation: home-course-card-slide-backward 280ms cubic-bezier(0.22, 1, 0.36, 1);
}

.viewer-live2d-placeholder-shell {
  position: relative;
  width: min(72%, 18rem);
  height: 84%;
  animation: viewer-live2d-float 6.8s ease-in-out infinite;
}

.viewer-live2d-placeholder__aura {
  position: absolute;
  inset: 10% 6% 12%;
  border-radius: 999px;
  background:
    radial-gradient(circle at 50% 28%, rgba(255, 255, 255, 0.82) 0%, rgba(255, 255, 255, 0) 44%),
    radial-gradient(circle at 50% 62%, rgba(168, 197, 172, 0.24) 0%, rgba(168, 197, 172, 0) 60%),
    radial-gradient(circle at 54% 72%, rgba(196, 149, 106, 0.12) 0%, rgba(196, 149, 106, 0) 58%);
  filter: blur(14px);
  animation: viewer-live2d-breathe 3.1s ease-in-out infinite;
}

.viewer-live2d-placeholder__orbit {
  position: absolute;
  left: 50%;
  top: 50%;
  border-radius: 999px;
  border: 1px solid rgba(214, 201, 183, 0.92);
  transform: translate(-50%, -50%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.38);
}

.viewer-live2d-placeholder__orbit--outer {
  width: 84%;
  height: 30%;
  top: 56%;
  animation: viewer-live2d-orbit 11s linear infinite;
}

.viewer-live2d-placeholder__orbit--inner {
  width: 58%;
  height: 22%;
  top: 56%;
  border-color: rgba(196, 149, 106, 0.42);
  animation: viewer-live2d-orbit-reverse 7.4s linear infinite;
}

.viewer-live2d-placeholder__core {
  position: absolute;
  left: 50%;
  bottom: 18%;
  width: 48%;
  aspect-ratio: 1;
  border-radius: 999px;
  transform: translateX(-50%);
  background:
    radial-gradient(circle at 34% 32%, rgba(255, 255, 255, 0.92) 0%, rgba(255, 255, 255, 0.08) 24%, transparent 30%),
    radial-gradient(circle at 50% 44%, #dceadf 0%, #a8c5ac 34%, #89b19a 62%, #7a9e7e 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.52),
    0 20px 34px rgba(90, 70, 50, 0.14);
}

.viewer-live2d-placeholder__core::after {
  content: '';
  position: absolute;
  inset: -10% -18%;
  border-radius: 999px;
  border: 1px solid rgba(255, 244, 227, 0.84);
  opacity: 0.84;
  transform: rotate(-18deg);
}

.viewer-live2d-placeholder__core::before {
  content: '';
  position: absolute;
  inset: auto 14% -18%;
  width: 100%;
  border-radius: 999px;
  height: 20%;
  background: radial-gradient(circle, rgba(114, 93, 73, 0.18), rgba(114, 93, 73, 0) 72%);
  filter: blur(10px);
}

.viewer-scrollbar-hidden {
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.viewer-scrollbar-hidden::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}

.viewer-dock-shell__content {
  padding-bottom: calc(var(--viewer-dock-content-gap) + env(safe-area-inset-bottom));
}

.viewer-dock-shell {
  pointer-events: none;
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 50;
  display: flex;
  justify-content: center;
  padding:
    0 0.75rem
    calc(var(--viewer-dock-offset) + env(safe-area-inset-bottom));
}

.viewer-dock {
  pointer-events: auto;
  display: flex;
  align-items: stretch;
  justify-content: space-between;
  gap: 0;
  width: min(calc(100vw - 1.5rem), 800px);
  min-height: var(--viewer-dock-height);
  padding: 0;
  border-radius: 999px;
  background: rgba(254, 250, 245, 0.78);
  box-shadow:
    0 16px 28px rgba(90, 70, 50, 0.09),
    inset 0 1px 0 rgba(255, 255, 255, 0.72);
  backdrop-filter: blur(18px);
  overflow: hidden;
}

.viewer-dock__slot {
  flex: 1 1 0;
  display: flex;
  justify-content: stretch;
  min-width: 0;
}

.viewer-dock__item {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: var(--viewer-dock-height);
  min-width: 0;
  border-radius: 0;
  padding: 0.48rem 0.9rem;
  color: #8f7f72;
  transition:
    background 160ms ease,
    color 160ms ease,
    box-shadow 160ms ease,
    transform 160ms ease;
}

.viewer-dock__item:hover {
  background: rgba(241, 234, 223, 0.72);
  color: #5d544b;
}

.viewer-dock__item--active {
  background: linear-gradient(180deg, rgba(233, 244, 231, 0.98) 0%, rgba(219, 237, 220, 0.92) 100%);
  color: #5c7d60;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.78),
    0 8px 18px rgba(122, 158, 126, 0.12);
}

.viewer-dock__item-inner {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  min-width: 0;
  height: 100%;
  width: 100%;
  white-space: nowrap;
}

.viewer-dock__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: currentColor;
}

.viewer-dock__icon--active {
  color: #5c7d60;
}

.viewer-dock__label {
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.01em;
  line-height: 1;
}

@media (max-width: 767px) {
  .viewer-dock-shell {
    padding:
      0 0.5rem
      calc(var(--viewer-dock-offset) + env(safe-area-inset-bottom));
  }

  .viewer-dock {
    width: min(calc(100vw - 1rem), 560px);
  }

  .viewer-dock__item {
    padding: 0.42rem 0.18rem;
  }

  .viewer-dock__item-inner {
    flex-direction: column;
    gap: 0.18rem;
  }

  .viewer-dock__label {
    font-size: 0.66rem;
  }
}

.landing-zoom-80 {
  zoom: 0.8;
}

@supports not (zoom: 0.8) {
  .landing-zoom-80 {
    width: 125%;
    transform: scale(0.8);
    transform-origin: top left;
  }
}

.viewer-gradient-text {
  background: linear-gradient(135deg, #c4956a, var(--viewer-primary-strong));
  -webkit-background-clip: text;
  color: transparent;
}

@keyframes viewer-float {
  0%,
  100% {
    transform: translate3d(0, 0, 0);
  }
  50% {
    transform: translate3d(0, -10px, 0);
  }
}

@keyframes viewer-live2d-float {
  0%,
  100% {
    transform: translate3d(0, 0, 0);
  }

  50% {
    transform: translate3d(0, -8px, 0);
  }
}

@keyframes viewer-live2d-breathe {
  0%,
  100% {
    transform: scale(0.96);
    opacity: 0.72;
  }

  50% {
    transform: scale(1.03);
    opacity: 1;
  }
}

@keyframes viewer-live2d-orbit {
  from {
    transform: translate(-50%, -50%) rotate(0deg);
  }

  to {
    transform: translate(-50%, -50%) rotate(360deg);
  }
}

@keyframes viewer-live2d-orbit-reverse {
  from {
    transform: translate(-50%, -50%) rotate(360deg);
  }

  to {
    transform: translate(-50%, -50%) rotate(0deg);
  }
}

.viewer-float-slow {
  animation: viewer-float 7s ease-in-out infinite;
}

.viewer-float-medium {
  animation: viewer-float 6s ease-in-out infinite;
  animation-delay: 0.8s;
}

.viewer-float-fast {
  animation: viewer-float 5.4s ease-in-out infinite;
  animation-delay: 1.2s;
}

